    if (n <= 0) {
        return List.of();
    }

    PriorityQueue<T> heap = new PriorityQueue<>(comparator);

    for (T item : items) {
        if (heap.size() < n) {
            heap.offer(item);
        } else if (comparator.compare(item, heap.peek()) > 0) {
            heap.poll();
            heap.offer(item);
        }
    }

    return heap.stream()
            .sorted(comparator.reversed())
            .toList();
